using OcctSharp.DocumentProjections;
using OcctSharp.XdeMetadataWorkspaces;
using OcctSharp.StepCafWorkspaces;
namespace OcctSharp.Tests.Shared;
internal static class BatchAXMetadataWorkflow {
 internal static readonly double[] DimensionValues=[2.5];
 internal static void Verify(MetadataSnapshot data,string entry){var row=data.Targets.Single(r=>r.Entry==entry);if(row.Surface is null||Math.Abs(row.Surface.Red-.2)>1e-6||row.MaterialEntry is null||data.Materials.Single(r=>r.Entry==row.MaterialEntry).Name!="材质🙂"||data.Materials[0].Pbr is not{Metallic:>=.39 and <=.41}||data.Views.Count!=1||data.Dimensions.Count!=1||data.Dimensions[0].Values?.Values.Single()!=2.5||!data.Dimensions[0].FirstShapeEntries.Contains(entry)||!data.Views[0].ShapeEntries.Contains(entry)||!data.Views[0].DimensionEntries.Contains(data.Dimensions[0].Entry))throw new InvalidOperationException("AX copied metadata/material/view/dimension association failed: "+System.Text.Json.JsonSerializer.Serialize(data));}
 internal static void Populate(XdeMetadataContext metadata,DocumentProjectionLabel shape){metadata.SetColors([new(shape,MetadataColorChannel.Surface,new(.2,.3,.4))]);_ = metadata.CreateMaterial("材质🙂",new(.2,.3,.4),.4,.6,[shape]);var dim=metadata.CreateDimension(20,"size","copied native kind",DimensionValues,[shape]);var view=metadata.CreateView("view",[shape],[dim]);metadata.SetViewLocked(view,true);}
 internal static void RunNative(){string directory=Path.Combine(Path.GetTempPath(),"OcctSharp.AX.Native."+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(directory);try{string seed=Path.Combine(directory,"seed.step"),output=Path.Combine(directory,"output.step");using var box=ShapeFactory.CreateBox(2,3,4);ShapeExchange.WriteStep(box,seed);using var imported=StepCafFiles.Read(seed);using var context=DocumentProjectionContext.Bind(imported.Document);using var metadata=XdeMetadataContext.Bind(context);var label=context.GetLabel(imported.Diagnostics.FreeRoots.Single().Entry);imported.Document.NewCommand();Populate(metadata,label);if(!imported.Document.CommitCommand())throw new InvalidOperationException("AX generated document command failed.");var detached=metadata.Snapshot([label]);Verify(detached,label.Entry);if(!imported.Document.Undo()||metadata.Snapshot([label]).Materials.Count!=0||!imported.Document.Redo())throw new InvalidOperationException("AX undo/redo lost command atomicity.");Verify(metadata.Snapshot([label]),label.Entry);var written=StepCafFiles.Write(context,output);using var reread=StepCafFiles.Read(output);if(written.Sha256!=reread.Diagnostics.Sha256||reread.Diagnostics.TransferRootCount!=1||reread.Diagnostics.FreeRoots.Count!=1)throw new InvalidOperationException("AX STEPCAF file/root identity failed.");imported.Dispose();Verify(detached,label.Entry);}finally{Directory.Delete(directory,true);}}
#if !DIRECT_MODULE_CONSUMER
 internal static void RunFacade(){string directory=Path.Combine(Path.GetTempPath(),"OcctSharp.AX.Facade."+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(directory);try{using var box=ShapeFactory.CreateBox(2,3,4);using var document=XdeDocument.Create();XdeLabel part,first,second,assembly;using(var transaction=document.BeginTransaction("AX instance metadata")){part=document.AddShape(box,"共享部件");assembly=document.AddAssembly("AX assembly");using var location=TopLocLocation.Identity;first=document.AddComponent(assembly,part,location);second=document.AddComponent(assembly,part,location);using var metadata=XdeMetadataContext.Bind(document.Projections);Populate(metadata,document.Projections.GetLabel(first.Entry));if(!transaction.Commit())throw new InvalidOperationException("AX XCAF command failed.");}using(var metadata=XdeMetadataContext.Bind(document.Projections)){Verify(metadata.Snapshot([document.Projections.GetLabel(first.Entry)]),first.Entry);if(metadata.Snapshot([document.Projections.GetLabel(second.Entry)]).Targets.Single().Surface is not null||metadata.Snapshot([document.Projections.GetLabel(part.Entry)]).Targets.Single().Surface is not null)throw new InvalidOperationException("AX repeated occurrence metadata leaked to another domain.");}foreach(var format in new[]{DocumentStorageFormat.BinXcaf,DocumentStorageFormat.XmlXcaf}){string file=Path.Combine(directory,format==DocumentStorageFormat.BinXcaf?"model.xbf":"model.xml");document.Save(file,format);string? diagnostics=Environment.GetEnvironmentVariable("OCCTSHARP_AX_DIAGNOSTICS_ROOT");if(diagnostics is not null){Directory.CreateDirectory(diagnostics);File.Copy(file,Path.Combine(diagnostics,Path.GetFileName(file)),true);}using var opened=XdeDocument.Open(file);using var metadata=XdeMetadataContext.Bind(opened.Projections);Verify(metadata.Snapshot([opened.Projections.GetLabel(first.Entry)]),first.Entry);if(opened.GetLabel(first.Entry).ReferredShape.Entry!=part.Entry||opened.GetLabel(second.Entry).ReferredShape.Entry!=part.Entry)throw new InvalidOperationException("AX XCAF source occurrence identity lost.");}string step=Path.Combine(directory,"assembly.step");var written=StepCafFiles.Write(document.Projections,step);using var imported=StepCafFiles.Read(step);if(imported.Diagnostics.Sha256!=written.Sha256||imported.Diagnostics.FreeRoots.Count!=1)throw new InvalidOperationException("AX assembly STEPCAF diagnostics failed.");using var conventional=XdeDocument.ReadStep(step);var roots=conventional.GetFreeShapes();if(roots.Length!=1)throw new InvalidOperationException("AX assembly conventional readback failed.");var components=roots[0].GetComponents();if(components.Count!=2||components[0].ReferredShape.Entry!=components[1].ReferredShape.Entry)throw new InvalidOperationException("AX actual STEP repeated occurrence/shared definition identity failed.");}finally{Directory.Delete(directory,true);}}
#endif
 internal static void Run(){RunNative();
#if !DIRECT_MODULE_CONSUMER
 RunFacade();
#endif
 }
}
